=== Views/blogFrontPage.cshtml
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = null;
}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>@Model.Title - Blog</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-gray-50 min-h-screen">
    <div class="container mx-auto px-4 py-12 max-w-4xl">
        <header class="mb-12 text-center">
            <h1 class="text-4xl font-bold text-gray-900 mb-4">@Model.Title</h1>
            <p class="text-xl text-gray-600">@Model.Intro</p>
        </header>

        <main class="space-y-12">
            @await Html.GetBlockGridHtmlAsync(Model, "body")

            <section class="mt-16">
                <h2 class="text-2xl font-bold text-gray-800 mb-8">Latest Posts</h2>

                <div class="space-y-8">
                    @foreach (var post in Model.Children<BlogPost>())
                    {
                        <article class="bg-white rounded-lg shadow-md overflow-hidden">
                            @if (post.ListingImage != null)
                            {
                                <img src="@post.ListingImage.GetCropUrl(width: 400, height: 250)"
                                     alt="@post.Title"
                                     class="w-full h-48 object-cover" />
                            }
                            <div class="p-6">
                                <h3 class="text-xl font-bold text-gray-900 mb-2">
                                    <a href="@post.Url()" class="hover:text-blue-600">@post.Title</a>
                                </h3>
                                <time class="text-sm text-gray-500 block mb-3">
                                    @post.PublishDate.ToString("MMMM dd, yyyy")
                                </time>
                                <p class="text-gray-700">@post.Excerpt</p>
                            </div>
                        </article>
                    }
                </div>
            </section>
        </main>
    </div>
</body>
</html>
