@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogPost>
@{
    Layout = null;
}

<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>@Model.Title</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-gray-50 min-h-screen">
    <div class="container mx-auto px-4 py-12 max-w-3xl">
        <article>
            <header class="mb-8 text-center">
                <h1 class="text-4xl font-bold text-gray-900 mb-4">@Model.Title</h1>
                <time class="text-sm text-gray-500">
                    Published: @Model.PublishDate.ToString("MMMM dd, yyyy")
                </time>
            </header>

            <main class="prose lg:prose-xl max-w-none">
                @await Html.GetBlockGridHtmlAsync(Model, "body")
            </main>

            <footer class="mt-12 pt-8 border-t border-gray-200">
                <a href="/" class="text-blue-600 hover:underline">
                    ← Back to Blog
                </a>
            </footer>
        </article>
    </div>
</body>
</html>

